from __future__ import annotations
from abc_creative_gold_v5_101_200_support import make_spec, register_craft
FACTS={
"Armor":"Protective clothing in historical/fantasy stories, often metal or layered material; real armor was heavy equipment, not magical invulnerability.","Bow":"Historical projectile weapon that launches arrows by stored limb/string energy; in this preschool fantasy set it stays picture-only.","Castle":"Fortified residence/defensive complex in many historical settings; towers, walls, gates, keeps, and moats vary by place and period.","Dragon":"Mythical creature appearing in many cultures with very different forms and meanings; no single universal dragon design exists.","Enchanted Book":"Fantasy story object whose magic comes from the fiction; a real book does not cast spells.","Fairy":"Folklore/fantasy being whose traits vary across traditions; wings and tiny size are not universal features.","Goblin":"Folklore/fantasy creature with many regional/literary versions; appearance and behavior depend on the story.","Horse":"Real domesticated equine animal often used in historical travel and stories; riding requires trained care and safety.","Invisible Cloak":"Fictional garment that hides a wearer in stories; real cloaks do not create invisibility.","Jester":"Historical court entertainer associated with comedy, music, performance, or satire; not every jester wore the same costume.","Knight":"Historical social/military role associated with mounted service in medieval Europe; fairy tales often simplify the history.","Lance":"Long pole weapon historically used by mounted fighters; picture-only fantasy item here.","Magic Wand":"Fictional prop used as a focus for magic in stories; real sticks/wands have no proven spell power.","Noble Crown":"Crown symbolizes royalty/status in stories/history; wearing one does not create authority outside its social context.","Ogre":"Folklore/fantasy humanoid creature often depicted as large; details vary by tale.","Princess":"Royal title for a female member of a ruling family in many systems; story princesses need not be passive or identical.","Quest Map":"Story map marks destinations, hazards, or clues for a fictional quest; plot information can be incomplete or misleading by design.","Royal Throne":"Ceremonial seat associated with a monarch/ruler; it symbolizes office rather than granting power by itself.","Spell Book":"Fantasy book containing fictional spells; it is a story device, not a real source of supernatural power.","Troll":"Folklore creature from Northern European traditions with many later fantasy reinterpretations.","Unicorn":"Mythical one-horned horse-like creature in European and other later fantasy traditions; it is not a real zoological species.","Village":"Settlement smaller than many towns/cities; in fairy tales it often anchors ordinary life before adventure.","Witch":"Figure in folklore, history, religion, and fantasy with widely varying meanings; fantasy witch traits should not be treated as facts about real people.","X-ray Mirror":"Project fantasy mirror with see-through powers; real mirrors reflect light and medical X-rays require specialized imaging equipment.","Yeti":"Folklore creature associated with Himalayan stories; no confirmed scientific evidence establishes a Yeti species.","Zodiac Amulet":"Fantasy amulet decorated with zodiac symbols; symbols have cultural/astrological meaning but no demonstrated magical force.","Amulet":"Small object worn/carried for symbolic, religious, protective, or decorative meaning; magical effects belong to belief/story context.","Bridge":"Structure crosses a gap, river, or road; in a quest it can act as a route choice without being magical.","Cauldron":"Large pot historically used for cooking/heating; fantasy stories may make it magical, but a real heated cauldron can burn.","Door":"Movable barrier controls access to a room/place; a 'magic door' is a plot device unless the story defines otherwise.","Elf":"Folklore/fantasy being from Germanic/Norse-derived and later traditions; modern pointed-ear depictions are only one convention.","Forest":"Real ecosystem dominated by trees/woodland vegetation; fairy tales may add fictional beings while the forest itself remains a real habitat type.","Giant":"Very large humanoid being in folklore/fantasy; giant size and temperament depend on the tale.","Hidden Door":"Concealed entrance in a story/building; hidden does not necessarily mean magical.","Island":"Land surrounded by water; a fantasy island can host invented places while island geography is real.","Key":"Object or code opens a lock; in stories it can also symbolize permission or discovery.","Lantern":"Portable light source; historical lanterns used flame while modern ones may use batteries, and fire safety matters.","Moon Gate":"Architectural circular opening/gateway associated especially with Chinese gardens; a fantasy story may repurpose it magically.","Orb":"Spherical object; crystal/magic orbs are fantasy divination props unless otherwise specified.","Potion":"Fantasy liquid with invented effects; real drinks/medicines should never be mixed or consumed as pretend potions.","Quill Pen":"Writing tool made historically from a prepared bird feather; it uses ink and requires careful handling.","Tower":"Tall structure or building section used for defense, observation, bells, living space, or symbolism depending context.","Village Well":"Well accesses groundwater; real wells are fall/water hazards and children stay behind barriers.","Xylophone Charm":"Project fantasy charm shaped like or themed around a xylophone; charm magic is fictional.","Yarn Doll":"Figure made from yarn; it can become a story character while long fibers still need supervised handling.","Arrow":"Projectile shot from a bow; weapon item remains picture-only in preschool fantasy play.","Cloak":"Loose outer garment; in stories it can signal role or concealment, but real fabric has no magic.","Hero":"Story role for a central character facing challenges; courage can include help, planning, retreat, or negotiation rather than fighting.","Jewel":"Cut/polished gemstone or decorative imitation; story jewels may mark clues/status but do not inherently possess magic.","King":"Male monarch title in some political systems; story kings vary widely and do not define real governance universally.","Magic Key":"Fictional key whose special power is defined by the story; real keys only operate compatible locks.","Royal Banner":"Flag/banner represents a ruler, house, place, or group in a story; symbols communicate identity rather than magic.","Sword":"Edged historical weapon; in this preschool story set it stays a picture/symbol and is never mimed as an attack.","X-shaped Gem":"Project gem with an X-like cut/outline; the X shape is a clue, not evidence of magical properties.","Zodiac Scroll":"Story scroll showing zodiac symbols; astrology is a cultural belief system, not established physical causation.",
}
ACTIONS={k:"Point to the fantasy weapon picture; no attack, aiming, or striking mime." for k in ("Bow","Lance","Arrow","Sword")}
ACTIONS.update({"Cauldron":"Point only; real heated pots are adult-only.","Potion":"Point; say story potion only—never mix or drink unknown liquids.","Village Well":"Point; mark a stay-back edge.","Horse":"Point; no riding stunt mime.","Quill Pen":"Air-write one short line; real ink stays supervised.","Yarn Doll":"Point; no yarn wrapping.","X-ray Mirror":"Point; say fantasy mirror, real X-ray is medical imaging.","Magic Wand":"Air-trace a star once; say the magic belongs to the story."})
